    @Test
    @DisplayName("A page that does not exist answers 404 (/suite-builder-no-such-page-883b31f0)")
    void aPageThatDoesNotExistIsNotFound() {
        Http.Answer answer = Http.get(SiteConfig.url("/suite-builder-no-such-page-883b31f0"), userAgent());
        // A site that answers anything to an address that cannot exist is filed as a bug (bugs/open/SITE-05.md): while
        // it is open, this test is blocked by it.
        if (KnownBugs.open("SITE-05") && answer.status() != 404) throw KnownBugs.blocked("SITE-05",
                "/suite-builder-no-such-page-883b31f0 answered " + answer.status()
                + ", not 404: missing pages look like pages");
        if (KnownBugs.open("SITE-05")) KnownBugs.looksFixed("SITE-05",
                "/suite-builder-no-such-page-883b31f0 answers 404");
        assertTrue(answer.status() == 404, "/suite-builder-no-such-page-883b31f0 answered " + answer.status()
                + ", not 404: a page that does not exist should say so");
    }
